class Solution {
    public String abbreviateProduct(int left, int right) {
        // count factors of p in n!
        long v2 = countFactor(right, 2) - countFactor(left - 1, 2);
        long v5 = countFactor(right, 5) - countFactor(left - 1, 5);
        long C = Math.min(v2, v5);

        // compute log sum for product' = product / 10^C
        double logSum = 0.0;
        for (int i = left; i <= right; ++i) {
            logSum += Math.log10(i);
        }
        logSum -= C; // remove trailing zeros

        long d = (long) Math.floor(logSum) + 1; // number of digits of product'

        // compute suffix modulo MOD = 10^10 to get full number if <=10 digits, or last 5 digits otherwise
        long MOD = 10_000_000_000L;
        long suffix = 1L;
        long rem2 = C, rem5 = C;
        for (int i = left; i <= right; ++i) {
            int val = i;
            while (rem2 > 0 && (val % 2) == 0) {
                val /= 2;
                rem2--;
            }
            while (rem5 > 0 && (val % 5) == 0) {
                val /= 5;
                rem5--;
            }
            suffix = (suffix * val) % MOD;
        }
        // Now build result
        if (d <= 10) {
            // suffix holds full number exactly
            return Long.toString(suffix) + "e" + C;
        } else {
            // compute first 5 digits
            double fractional = logSum - Math.floor(logSum);
            double leadPow = Math.pow(10, fractional + 4); // get first 5 digits
            int first5 = (int) Math.floor(leadPow + 1e-9); // small eps to avoid FP issues
            long last5 = suffix % 100000L;
            String last5s = String.format("%05d", last5);
            String first5s = String.format("%d", first5);
            return first5s + "..." + last5s + "e" + C;
        }
    }

    private long countFactor(int n, int p) {
        long cnt = 0;
        while (n > 0) {
            n /= p;
            cnt += n;
        }
        return cnt;
    }
}

